// Hand-written helpers on top of the API generated by UniFFI (not touched by
// scripts/generate-bindings.sh, which only replaces com/termoak/ffi).
package com.termoak.kit

import com.termoak.ffi.ApiErrorInfo
import com.termoak.ffi.TermoakException
import com.termoak.ffi.apiErrorInfo

/**
 * HTTP status, stable code and extra fields of a server error (or of a vault
 * or network rule checked on the device, with status 0):
 * `e.apiError?.code == "shared_vaults"`, `e.apiError?.detailsJson` with its
 * `vaults`... `null` for other errors.
 */
val TermoakException.apiError: ApiErrorInfo?
    get() = message?.let { apiErrorInfo(it) }
